const page=document.body.dataset.page,content=document.querySelector("#content"),title=document.querySelector("#page-title"),locale=TCUI.locale;
const titles=TCUI.pageTitles[locale];
title.textContent=titles[page]||(locale==="zh-CN"?"工作台":"Dashboard");const navPage=page==="trade-plan-detail"?"trade-plans":page==="position-detail"?"positions":page==="trade-review-detail"?"trade-reviews":page==="companion-detail"?"companion":page==="market-snapshot-detail"||page==="watchlist-snapshot"||page==="symbol-overview"?"market-snapshots":page.replace("-detail","");document.querySelector(`[data-nav="${navPage}"]`)?.classList.add("active");
const esc=v=>String(v??"—").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt=v=>v?new Date(v).toLocaleString(locale,{hour12:false}):"—";
const zh=TCUI.statusCopy[locale];
const tag=v=>`<span class="tag ${["CONNECTED","RUNNING","ACTIVE","NOTIFIED","COMPLETED","VALID","OK"].includes(v)?"good":["DEGRADED","DETECTED","INBOX","WAITING_APPROVAL","WARMUP","WATCH","REVIEW","PENDING"].includes(v)?"warn":["FAILED","INVALIDATED","REJECTED","CRITICAL"].includes(v)?"bad":["PLAN","COMPANION","READY"].includes(v)?"info":""}">${esc(zh[v]||v||(locale==="zh-CN"?"未知":"Unknown"))}</span>`;
const apiCache=new Map();async function api(url,options={}){const method=(options.method||"GET").toUpperCase(),key=method+":"+url;if(method==="GET"&&apiCache.has(key))return apiCache.get(key);const request=fetch(url,{...options,headers:{"Content-Type":"application/json",...(options.headers||{})}}).then(async r=>{if(r.status===401){location="/dashboard/login";throw Error("未授权")}const body=await r.json();if(!r.ok)throw Error(body.detail||"请求失败");if(method!=="GET")apiCache.clear();return body});if(method==="GET")apiCache.set(key,request);try{return await request}catch(e){apiCache.delete(key);throw e}}
const empty=(titleText,detail="")=>`<div class="empty"><strong>${esc(titleText)}</strong>${detail?`<small>${esc(detail)}</small>`:""}</div>`;
function table(headers,rows,emptyTitle,emptyDetail){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")||`<tr><td colspan="${headers.length}">${empty(emptyTitle||(locale==="zh-CN"?"暂无记录":"No records"),emptyDetail||"")}</td></tr>`}</tbody></table></div>`}
async function home(){const [d,snapshots,plans,portfolios,reviews,analyses]=await Promise.all([api("/api/dashboard/summary"),api("/api/market-snapshots?page_size=6"),api("/api/trade-plans?limit=6"),api("/api/portfolios?page_size=6"),api("/api/reviews?limit=6"),api("/api/companion-analyses?limit=6")]);const portfolioItems=portfolios.items||[],openHoldings=portfolioItems.reduce((sum,x)=>sum+(x.open_holdings||0),0),watchlistCount=portfolioItems.reduce((sum,x)=>sum+(x.watchlist_count||0),0),activePlans=(plans.items||[]).filter(x=>["PLAN","COMPANION"].includes(x.lifecycle_stage)).length;
const kpis=locale==="zh-CN"?[["市场状态",d.market_regime.regime,"当前市场环境","/dashboard/market-regime"],["今日信号",d.candidate_pool.total,"候选信号","/dashboard/candidates"],["活跃交易计划",activePlans,"PLAN / COMPANION","/dashboard/trade-plans"],["持仓数量",openHoldings,"Trade Companion 记录","/dashboard/portfolios"],["已完成复盘",d.today.reviews_completed,"今日完成","/dashboard/trade-reviews"],["AI 分析数量",(analyses.items||[]).length,"最近记录","/dashboard/companion"]]:[["Market Regime",d.market_regime.regime,"Current environment","/dashboard/market-regime"],["Signals Today",d.candidate_pool.total,"Candidate signals","/dashboard/candidates"],["Active Trade Plans",activePlans,"PLAN / COMPANION","/dashboard/trade-plans"],["Open Holdings",openHoldings,"Recorded in Trade Companion","/dashboard/portfolios"],["Reviews Completed",d.today.reviews_completed,"Completed today","/dashboard/trade-reviews"],["AI Analyses",(analyses.items||[]).length,"Recent records","/dashboard/companion"]];
content.innerHTML=`<div class="grid metrics">${kpis.map(x=>metric(x[0],x[1],x[2],x[3])).join("")}</div><div class="dashboard-panels"><section class="card"><div class="card-header"><h2>${locale==="zh-CN"?"市场概览":"Market Overview"}</h2><a href="/dashboard/market-snapshots">${locale==="zh-CN"?"查看全部":"View all"}</a></div>${snapshotTable((snapshots.items||[]).slice(0,6))}</section><section class="card"><div class="card-header"><h2>${locale==="zh-CN"?"近期交易机会":"Recent Opportunities"}</h2><a href="/dashboard/opportunities">${locale==="zh-CN"?"查看全部":"View all"}</a></div>${opTable((d.latest_opportunities||[]).slice(0,5))}</section><section class="card"><div class="card-header"><h2>${locale==="zh-CN"?"投资组合概览":"Portfolio Overview"}</h2><a href="/dashboard/portfolios">${locale==="zh-CN"?"管理":"Manage"}</a></div><div class="grid">${compactStat(locale==="zh-CN"?"持仓":"Holdings",openHoldings)}${compactStat("Watchlist",watchlistCount)}${compactStat("LONG / SHORT",`${d.today.long} / ${d.today.short}`)}${compactStat(locale==="zh-CN"?"组合数量":"Portfolios",portfolioItems.length)}</div></section></div><div class="dashboard-lower"><section class="card"><div class="card-header"><h2>${locale==="zh-CN"?"近期交易计划":"Recent Trade Plans"}</h2><a href="/dashboard/trade-plans">${locale==="zh-CN"?"查看全部":"View all"}</a></div>${planDashboardTable(plans.items||[])}</section><section class="card"><div class="card-header"><h2>${locale==="zh-CN"?"近期复盘与 AI 分析":"Recent Reviews & AI"}</h2><a href="/dashboard/trade-reviews">${locale==="zh-CN"?"查看复盘":"View reviews"}</a></div>${recentResearchList(reviews.items||[],analyses.items||[])}</section></div>`;updateTopbar(d)}
function metric(k,v,helper="",url=""){const body=`<small>${esc(k)}</small><strong>${esc(v)}</strong>${helper?`<span class="fine">${esc(helper)}</span>`:""}`;return url?`<a class="card metric clickable" href="${url}">${body}</a>`:`<div class="card metric">${body}</div>`}
function compactStat(label,value){return `<div class="service"><span class="muted">${esc(label)}</span><b>${esc(value)}</b></div>`}
function snapshotTable(items){return table([locale==="zh-CN"?"标的":"Symbol",locale==="zh-CN"?"价格":"Price",locale==="zh-CN"?"候选":"Candidate",locale==="zh-CN"?"计划":"Plan"],items.map(x=>`<tr><td><a href="/dashboard/symbols/${encodeURIComponent(x.symbol)}"><b>${esc(x.symbol)}</b></a></td><td class="numeric">${esc(x.latest_price)}</td><td>${tag(x.candidate_signal)}</td><td>${tag(x.trade_plan_status)}</td></tr>`),locale==="zh-CN"?"暂无市场快照":"No market snapshots",locale==="zh-CN"?"添加关注标的并同步行情后将在这里显示。":"Watch symbols appear here when local market data is available.")}
function planDashboardTable(items){return table([locale==="zh-CN"?"标的":"Symbol",locale==="zh-CN"?"阶段":"Stage",locale==="zh-CN"?"评分":"Score"],items.slice(0,6).map(x=>`<tr><td><a href="/dashboard/trade-plans/${encodeURIComponent(x.plan_id)}"><b>${esc(x.symbol)}</b></a></td><td>${tag(x.lifecycle_stage)}</td><td class="numeric">${esc(x.score)}</td></tr>`),locale==="zh-CN"?"暂无交易计划":"No trade plans",locale==="zh-CN"?"策略运行后，符合条件的机会会出现在这里。":"Qualified opportunities appear here after the strategy runs.")}
function recentResearchList(reviews,analyses){const items=[...reviews.slice(0,3).map(x=>({label:`${x.symbol} · ${x.result}`,time:x.review_time,status:x.result})),...analyses.slice(0,3).map(x=>({label:`${x.source?.symbol||"—"} · AI`,time:x.request_completed_at||x.created_at,status:x.status}))].sort((a,b)=>String(b.time).localeCompare(String(a.time)));return items.length?items.map(x=>`<div class="service"><div><b>${esc(x.label)}</b><p class="muted">${fmt(x.time)}</p></div>${tag(x.status)}</div>`).join(""):empty(locale==="zh-CN"?"暂无复盘或 AI 分析":"No reviews or AI analyses",locale==="zh-CN"?"交易结束后可生成客观复盘，再由 AI 解释已有结果。":"Completed trades can be reviewed and then explained by AI.")}
function updateTopbar(d){const byName=Object.fromEntries((d.services||[]).map(x=>[x.service_name,x]));setBadge("health-badge",locale==="zh-CN"?"系统":"System",d.system_health.status);setBadge("opend-badge","OpenD",byName.opend?.status||"UNKNOWN");setBadge("ai-badge","AI",d.ai_review.enabled?"ACTIVE":"DISABLED");setBadge("telegram-badge","Telegram",byName.telegram?.status||"UNKNOWN")}
function setBadge(id,label,status){const node=document.querySelector(`#${id}`);if(!node)return;node.textContent=`${label} ${zh[status]||status}`;node.className=`status-pill ${["OK","CONNECTED","RUNNING","ACTIVE"].includes(status)?"good":["DEGRADED","PENDING"].includes(status)?"warn":["FAILED","DISCONNECTED"].includes(status)?"bad":"neutral"}`}
function service(s){return `<div class="service"><div><b>${esc(s.service_name)}</b><p class="muted">心跳 ${fmt(s.last_heartbeat_at)} · 成功 ${fmt(s.last_success_at)}</p>${s.last_error_message?`<small class="muted">${esc(s.last_error_message)}</small>`:""}</div>${tag(s.status)}</div>`}
function opTable(items){return table(locale==="zh-CN"?["标的","周期","方向","策略","评分","状态","发现时间"]:["Symbol","Timeframe","Direction","Strategy","Score","Status","Detected"],items.map(x=>`<tr><td><a href="/dashboard/opportunities/${x.id}">${esc(x.symbol)}</a></td><td>${esc(x.timeframe)}</td><td>${esc(zh[x.direction]||x.direction)}</td><td>${esc(x.strategy_name)}</td><td class="numeric">${esc(x.score)}</td><td>${tag(x.status)}</td><td>${fmt(x.detected_at)}</td></tr>`),locale==="zh-CN"?"暂无交易机会":"No opportunities",locale==="zh-CN"?"符合条件的机会将在策略运行后显示。":"Qualified opportunities appear after the strategy runs.")}
function candidateTable(items){return table(locale==="zh-CN"?["排名","标的","方向","LONG","SHORT","最终评分","状态"]:["Rank","Symbol","Direction","LONG","SHORT","Final Score","Status"],items.map(x=>`<tr><td>${esc(x.rank)}</td><td><a href="/dashboard/candidates/${x.id}">${esc(x.symbol)}</a></td><td>${tag(x.direction)}</td><td class="numeric">${esc(x.long_score??"—")}</td><td class="numeric">${esc(x.short_score??"—")}</td><td class="numeric">${esc(x.final_score)}</td><td>${tag(x.status||"CANDIDATE")}</td></tr>`),locale==="zh-CN"?"暂无候选标的":"No candidates",locale==="zh-CN"?"候选池运行后将在这里显示结果。":"Candidate Pool results appear here after it runs.")}
