async function candidates(){content.innerHTML=`<div class="actions"><button id="build">重建候选池</button><button id="refresh" class="ghost">刷新当前池</button></div><div class="filters"><input id="c-symbol" placeholder="Ticker"><select id="c-direction"><option value="">全部方向</option><option>LONG</option><option>SHORT</option><option>BOTH</option></select><input id="c-score" type="number" placeholder="最低分"><button id="c-filter">筛选</button></div><div id="candidate-list"></div>`;async function load(){const q=new URLSearchParams({limit:"200"});if(cSymbol.value)q.set("symbol",cSymbol.value);if(cDirection.value)q.set("direction",cDirection.value);if(cScore.value)q.set("min_score",cScore.value);const d=await api("/api/candidate-pool?"+q);document.querySelector("#candidate-list").innerHTML=candidateTable(d.items)}const cSymbol=document.querySelector("#c-symbol"),cDirection=document.querySelector("#c-direction"),cScore=document.querySelector("#c-score");document.querySelector("#c-filter").onclick=load;document.querySelector("#build").onclick=async()=>{await api("/api/candidate-pool/build",{method:"POST"});location.reload()};document.querySelector("#refresh").onclick=async()=>{await api("/api/candidate-pool/refresh",{method:"POST"});location.reload()};load()}
