async function opportunities(){content.innerHTML=`<div class="filters"><input id="f-symbol" placeholder="Ticker"><select id="f-status"><option value="">全部状态</option>${["DETECTED","NOTIFIED","ACTIVE","INVALIDATED","EXPIRED"].map(x=>`<option>${x}</option>`)}</select><input id="f-score" type="number" min="0" max="100" placeholder="最低评分"><button id="filter">筛选</button></div><div id="op-list"></div>`;async function load(){const q=new URLSearchParams({limit:"100"});if(fSymbol.value)q.set("symbol",fSymbol.value);if(fStatus.value)q.set("status",fStatus.value);if(fScore.value)q.set("min_score",fScore.value);const d=await api("/api/opportunities?"+q);document.querySelector("#op-list").innerHTML=opTable(d.items)}const fSymbol=document.querySelector("#f-symbol"),fStatus=document.querySelector("#f-status"),fScore=document.querySelector("#f-score");document.querySelector("#filter").onclick=load;load()}
